'use strict';
const assert=require('node:assert/strict'),Y=require('../js/yahoo-season-v1');require('../js/yahoo-season-v1');const Sync=require('../js/yahoo-sync-v1');
const fixture=require('./fixtures/yahoo/league_bundle_2026.json');const bundle=JSON.parse(JSON.stringify(fixture));bundle.weekContext={verified:true,selectedWeek:8,requestedWeek:8,yahooCurrentWeek:7};bundle.league.leagues[0].currentWeek=7;bundle.matchups.week=8;bundle.teamRosters={};bundle.teams.teams[0].roster[0].rosterSlot='FLEX';bundle.teams.teams[0].roster[0].eligiblePositions=['RB','FLEX'];bundle.teams.teams[0].roster[0].actualPoints=0;
const profile={id:'p1',season:2026},snapshot=Y.buildSeasonSnapshot(bundle,{profile});let n=0;const test=(name,fn)=>{fn();n++;console.log('PASS '+name);};
test('selected and current weeks stay distinct',()=>{assert.equal(snapshot.league.currentWeek,7);assert.equal(snapshot.seasonMode.fantasyWeek,8);assert.equal(snapshot.teams[0].roster[0].actualPointsWeek,8);});
test('Yahoo nested bye week remains available',()=>assert.equal(Y.normalizeYahooPlayer({player_id:'1',name:'Player',bye_weeks:{week:'8'}}).byeWeek,8));
test('explicit team roster overrides embedded current roster',()=>{const teams=Y.normalizeTeams({teams:[{teamKey:'t',roster:[{name:'Old',yahooPlayerId:'old'}]}]},{t:{player_key:'461.p.1',player_id:'1',name:{full:'Selected'},selected_position:{position:'BN'}}});assert.equal(teams[0].roster[0].name,'Selected');assert.equal(teams[0].roster[0].rosterSlot,'BN');});
test('slots and eligibility preserved',()=>{assert.equal(snapshot.teams[0].roster[0].rosterSlot,'FLEX');assert.deepEqual(snapshot.teams[0].roster[0].eligiblePositions,['RB','FLEX']);});
(async()=>{const map=new Map(),storage={getItem:k=>map.get(k)||null,setItem:(k,v)=>map.set(k,v)};let response=bundle,requested;const c=Sync.createController({seasonApi:Y,storage,transport:{sync:async(k,w)=>{requested=w;return response;}}});c.mapLeague(profile,{leagueKey:bundle.leagueKey});await c.sync({profile,week:8});test('controller forwards requested week',()=>assert.equal(requested,8));response={...bundle,weekContext:{verified:true,selectedWeek:7}};await assert.rejects(c.sync({profile,week:8}),/did not verify/);test('wrong-week response preserves previous valid snapshot',()=>{assert.equal(c.read('p1').snapshot.seasonMode.fantasyWeek,8);assert.equal(c.read('p1').sync.status,'STALE');});response={...bundle,weekContext:{verified:true,selectedWeek:9},errors:{liveWeek:'missing'},liveWeek:null};await c.sync({profile,week:9});test('failed subsystem does not borrow prior week',()=>assert.equal(c.read('p1').snapshot.liveWeek,null));console.log(`${n}/${n} passed`);})().catch(e=>{console.error(e);process.exitCode=1});
